<?php
require __DIR__.'/invoices.php';
require_once APPPATH.'services/NativeCompanyCustomFields.php';
NativeCompanyCustomFieldSchema::ensure($db,$p);
$fields=new NativeCompanyCustomFields($db,$p);
$definition=NativeCompanyCustomFields::definition(['fieldto'=>'items','name'=>'Synthetic invoice line field','type'=>'input','active'=>1]);
$db->query('INSERT INTO '.$p.'company_custom_fields(issuer_id,fieldto,slug,definition_json,revision) VALUES(?,?,?,?,1)',[$a,'items','synthetic_line',json_encode($definition,JSON_THROW_ON_ERROR)]);
$field=NativeCompanyResourceId::encode('company_custom_field',$db->insert_id());
$line=(int)$db->query("SELECT id FROM {$p}itemable WHERE rel_type='invoice' AND rel_id=? ORDER BY id",[$branded])->row_array()['id'];
$tables=array_merge($fields->tableNames(),['itemable','invoices']);
$before=$db->query('SELECT * FROM '.$p.'invoices ORDER BY id')->result_array();
IssuerTransaction::run($db,$p,$tables,fn()=>$fields->saveInOwnedTransaction($a,7,'items',$line,[$field=>'Real line, not catalog item']));
essentialCheck($fields->values($a,7,'items',$line)[$field]==='Real line, not catalog item','invoice line custom field uses actual itemable parent');
$stored=$db->query('SELECT source_kind,source_id FROM '.$p.'company_custom_field_values WHERE issuer_id=?',[$a])->row_array();
essentialCheck($stored['source_kind']==='invoice_item'&&(int)$stored['source_id']===$line,'invoice line identity does not alias catalog items');
essentialThrows(fn()=>$fields->values($b,7,'items',$line),'company_invoice_access_denied','other issuer cannot read itemable metadata');
essentialThrows(fn()=>IssuerTransaction::run($db,$p,$fields->tableNames(),fn()=>$fields->saveInOwnedTransaction($a,7,'items',$line,[$field=>'unsafe'])),'issuer_owned_transaction_required','partial transaction cannot mutate line metadata');
$db->query("UPDATE {$p}issuers_staff SET can_view=1 WHERE issuer_id=? AND staff_id=12",[$a]);
essentialCheck(count($fields->invoiceItemDefinitions($a,12,$branded))===1,'invoice-view actor without catalogue permissions reads line definitions');
essentialCheck(count($fields->invoiceItemDefinitions($a,12,null,[],'create'))===1,'invoice-create actor uses native definitions without catalogue authority');
essentialThrows(fn()=>IssuerTransaction::run($db,$p,$tables,fn()=>$fields->saveInOwnedTransaction($a,12,'items',$line,[$field=>'denied'])),'company_invoice_access_denied','create-only actor cannot edit an existing line');
$db->query("UPDATE {$p}itemable SET rel_type='estimate' WHERE id=?",[$line]);
essentialThrows(fn()=>$fields->values($a,7,'items',$line),'native_custom_field_denied','same raw item ID for another document family is rejected');
$db->query("UPDATE {$p}itemable SET rel_type='invoice' WHERE id=?",[$line]);
essentialCheck($db->query('SELECT * FROM '.$p.'invoices ORDER BY id')->result_array()===$before,'line metadata never changes financial invoice rows');
echo 'Native invoice line custom fields: '.$GLOBALS['essentialChecks']." cumulative PASS.\n";
$db->failOn='UPDATE '.$p.'company_custom_field_values';
essentialThrows(fn()=>IssuerTransaction::run($db,$p,$tables,fn()=>$fields->saveInOwnedTransaction($a,7,'items',$line,[$field=>'must roll back'])),'issuer_storage_failed','failed metadata write rolls back');$db->failOn=null;
essentialCheck($fields->values($a,7,'items',$line)[$field]==='Real line, not catalog item','rollback preserves previous exact metadata');
$db->query("UPDATE {$p}issuers_staff SET can_view=0 WHERE issuer_id=? AND staff_id=12",[$a]);
essentialThrows(fn()=>$fields->values($a,12,'items',$line),'company_invoice_access_denied','revoked invoice reader cannot hydrate line fields');
echo 'Invoice line metadata rollback/revocation: '.$GLOBALS['essentialChecks']." cumulative PASS.\n";
